G = load()

def print_grid(g, name=""):
    print(f"\n=== {name} ===")
    for i, row in enumerate(g):
        print(" ".join(f"{x}" for x in row))

for key, g in sorted(G.items()):
    print_grid(g, key)

# Analyze the pattern and implement solution
def solve(grid):
    """Draw lines between special points (non-background) on same row/column"""
    h = len(grid)
    w = len(grid[0])

    # Find background color (most common)
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    background = max(counts, key=counts.get)

    # Find special points
    special = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background:
                special.append((r, c))

    result = [row[:] for row in grid]

    # Draw lines between all pairs sharing row or column
    fill_color = 3
    for i in range(len(special)):
        for j in range(i+1, len(special)):
            r1, c1 = special[i]
            r2, c2 = special[j]

            # Check if they share row or column
            if r1 == r2:  # Same row
                min_c, max_c = min(c1, c2), max(c1, c2)
                for c in range(min_c, max_c + 1):
                    if grid[r1][c] == background:
                        result[r1][c] = fill_color
            elif c1 == c2:  # Same column
                min_r, max_r = min(r1, r2), max(r1, r2)
                for r in range(min_r, max_r + 1):
                    if grid[r][c1] == background:
                        result[r][c1] = fill_color

    return result

# Test on demo pair 1
input_grid = G['Demo pair 1 input']
output_grid = G['Demo pair 1 output']

result = solve(input_grid)

